const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'

export function scan(src) {
  const s = Array.from(src)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advTo = (j) => {
    while (i < j) adv()
  }

  // digit run allowing single underscores between digits; returns end index
  const run = (j, test) => {
    if (!test(s[j])) return j
    j++
    for (;;) {
      if (test(s[j])) j++
      else if (s[j] === '_' && test(s[j + 1])) j += 2
      else return j
    }
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const sl = line
    const sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let depth = 0
      while (i < n) {
        if (s[i] === '/' && s[i + 1] === '*') {
          depth++
          adv()
          adv()
        } else if (s[i] === '*' && s[i + 1] === '/') {
          depth--
          adv()
          adv()
          if (depth === 0) break
        } else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i
      while (j < n && isIdentChar(s[j])) j++
      const text = s.slice(i, j).join('')
      advTo(j)
      push(KEYWORDS.has(text) ? 'keyword' : 'ident', text)
      continue
    }
    if (isDigit(c)) {
      let j = i
      const p = (s[i + 1] || '').toLowerCase()
      const test = c === '0' && p === 'x' ? isHex : c === '0' && p === 'b' ? (d) => d === '0' || d === '1' : c === '0' && p === 'o' ? (d) => d !== undefined && d >= '0' && d <= '7' : null
      let bad = false
      if (test) {
        j = i + 2
        if (!test(s[j])) bad = true
        else j = run(j, test)
      } else {
        j = run(j, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          if (isDigit(s[j + 1])) j = run(j + 1, isDigit)
          else if ((s[j + 1] === '+' || s[j + 1] === '-') && isDigit(s[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (bad || isIdentChar(s[j])) {
        while (isIdentChar(s[j])) j++
        throw new ScanError(sl, sc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const text = s.slice(i, j).join('')
      advTo(j)
      push('number', text)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      const text = s.slice(i + 2, j).join('')
      advTo(j + 1)
      push('rawstring', JSON.stringify(text))
      continue
    }
    if (c === '"') {
      adv()
      let val = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '"') {
          adv()
          break
        }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') {
          val += d
          adv()
          continue
        }
        const bl = line
        const bc = col
        if (i + 1 >= n) {
          adv()
          throw new ScanError(sl, sc, 'unterminated string')
        }
        const e = s[i + 1]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          val += simple[e]
          adv()
          adv()
        } else if (e === 'x') {
          if (!isHex(s[i + 2]) || !isHex(s[i + 3])) throw new ScanError(bl, bc, 'invalid escape \\x')
          val += String.fromCodePoint(parseInt(s[i + 2] + s[i + 3], 16))
          advTo(i + 4)
        } else if (e === 'u') {
          let j = i + 2
          if (s[j] !== '{') throw new ScanError(bl, bc, 'invalid escape \\u')
          j++
          const st = j
          while (isHex(s[j])) j++
          if (j === st || s[j] !== '}') throw new ScanError(bl, bc, 'invalid escape \\u')
          const cp = parseInt(s.slice(st, j).join(''), 16)
          if (cp > 0x10ffff) throw new ScanError(bl, bc, 'invalid escape \\u')
          val += String.fromCodePoint(cp)
          advTo(j + 1)
        } else throw new ScanError(bl, bc, `invalid escape \\${e}`)
      }
      push('string', JSON.stringify(val))
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.has(two)) {
      adv()
      adv()
      push('punct', two)
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      push('punct', c)
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
