import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/
const int = (s, field, least) => {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
      if (d !== 'event' && events.length) fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const capacity = int(t[2], 'capacity', 1)
        const refill = int(t[3], 'refill', 0)
        const per = int(t[4], 'per', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
      } else if (d === 'window') {
        if (t.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const limit = int(t[2], 'limit', 0)
        const span = int(t[3], 'span', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'window', name: t[1], limit, span })
      } else if (d === 'route') {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
        routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
      } else {
        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = int(t[1], 'tick', 0)
        if (!NAME.test(t[2])) fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const stats = new Map()
  const out = []
  let ta = 0
  let td = 0
  const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)
  for (const { tick, key } of events) {
    const prefix = prefixes.find((p) => key.startsWith(p))
    let denier = null
    if (prefix !== undefined) {
      const ps = routes.get(prefix)
      const sts = ps.map((p) => {
        const k = p.name + '\0' + key
        let s = states.get(k)
        if (!s) {
          s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
          states.set(k, s)
        }
        if (p.kind === 'bucket') {
          const cap = p.capacity * p.per
          s.num += p.refill * (tick - s.last)
          if (s.num > cap) s.num = cap
          s.last = tick
        } else {
          const lim = tick - p.span
          s.ticks = s.ticks.filter((x) => x > lim)
        }
        return s
      })
      for (let i = 0; i < ps.length; i++) {
        const p = ps[i]
        const ok = p.kind === 'bucket' ? sts[i].num >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
      if (denier === null) {
        ps.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].num -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (denier === null) { st.a++; ta++ } else { st.d++; td++ }
    out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') +
    `total allowed=${ta} denied=${td}\n`
}

