{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.map.keys()].sort(cmp)
}

function ser(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const keys = sortedKeys(node)
      if (!keys.length) return '{}'
      return '{\n' + keys.map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.map.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array': {
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((n) => pad + ser(n, indent + 1)).join(',\n') + '\n' + end + ']'
    }
    case 'string':
      return JSON.stringify(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : path + '.' + k
        const c = node.map.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const table = () => ({ t: 'table', map: new Map(), defined: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  fail(m) {
    throw new Error(m)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  // at end of line or at a comment
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  quoted() {
    const q = this.s[this.i]
    this.i++
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) this.fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) this.fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i + 1))
          this.fail('invalid escape \\' + cp)
        }
      } else {
        out += c
        this.i++
      }
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (st === this.i) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }
  value(prefix) {
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.s[this.i] !== undefined && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    this.fail('invalid value ' + w)
