        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === ']') continue
      this.fail('unterminated array')
    }
  }
  inline(prefix) {
    this.i++
    const t = table()
    t.defined = true
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(prefix)
      assign(t, names, v, prefix)
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === '}') {
        this.i++
        return t
      }
      this.fail('unterminated inline table')
    }
  }
}

const join = (p, n) => (p ? p + '.' + n : n)

// Walk through names (all but the last), creating tables.
function walk(cur, names, prefix, upto) {
  let path = prefix
  for (let k = 0; k < upto; k++) {
    const n = names[k]
    path = join(path, n)
    let nx = cur.map.get(n)
    if (!nx) {
      nx = table()
      cur.map.set(n, nx)
    }
    if (nx.t === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
    if (nx.t !== 'table') throw new Error(path + ' is not a table')
    cur = nx
  }
  return { cur, path }
}

