  const r = walk(cur, names, prefix, names.length - 1)
  const last = names[names.length - 1]
  if (r.cur.map.has(last)) throw new Error(`key ${join(r.path, last)} is defined twice`)
  r.cur.map.set(last, value)
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = table()
  root.defined = true
  let current = root
  let lineNo = 0
  try {
    for (const line of lines) {
      lineNo++
      const p = new LineParser(line)
      p.ws()
      const c = line[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        current = header(p, root)
        continue
      }
      const names = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') throw new Error('expected key = value')
      p.i++
      p.ws()
      const v = p.value(names.join('.'))
      p.ws()
      if (!p.atEnd()) throw new Error('trailing text after a value')
      assign(current, names, v, currentPrefix.get(current) || '')
    }
  } catch (e) {
    if (e instanceof ParseError) throw e
    throw new ParseError(e.message, lineNo)
  }
  return root
}

const currentPrefix = new WeakMap()

function header(p, root) {
  p.i++
  const aot = p.s[p.i] === '['
  if (aot) p.i++
  p.ws()
  const names = p.dotted()
  p.ws()
  const closeFail = () => {
    throw new Error('unterminated table header')
  }
  if (p.s[p.i] !== ']') closeFail()
  p.i++
  if (aot) {
    if (p.s[p.i] !== ']') closeFail()
    p.i++
  }
  p.ws()
  if (!p.atEnd()) throw new Error('trailing text after a table header')

  const full = names.join('.')
  const r = walk(root, names, '', names.length - 1)
  const last = names[names.length - 1]
  const ex = r.cur.map.get(last)
  let result
  if (aot) {
    if (!ex) {
      const a = { t: 'array', items: [], aot: true }
      r.cur.map.set(last, a)
      result = table()
      a.items.push(result)
    } else if (ex.t === 'array' && ex.aot) {
      result = table()
      ex.items.push(result)
    } else throw new Error(full + ' is not an array of tables')
  } else {
    if (!ex) {
      result = table()
      r.cur.map.set(last, result)
    } else if (ex.t === 'table') {
      if (ex.defined) throw new Error(`table ${full} is defined twice`)
      result = ex
    } else throw new Error(full + ' is not a table')
    result.defined = true
  }
  currentPrefix.set(result, full)
  return result
}
"}

