  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (w[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const history = new Map(cands.map((c) => [c, []]))
const out = []
let winner = null
let round = 0
for (;;) {
  round++
  const votes = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  let total = 0n
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      votes.set(c, votes.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of votes) history.get(c).push(v)
  const order = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${round}: ` + order.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = order.find(([, v]) => v * 2n > active)
  if (top) {
    winner = top[0]
    break
  }
  let min = order[order.length - 1][1]
  let S = order.filter(([, v]) => v === min).map(([c]) => c)
  for (let r = 0; S.length > 1 && r < round; ) {
    const m = S.reduce((a, c) => (history.get(c)[r] < a ? history.get(c)[r] : a), history.get(S[0])[r])
    const keep = S.filter((c) => history.get(c)[r] === m)
    if (keep.length < S.length) {
      S = keep
      r = 0
    } else r++
  }
  const elim = S.reduce((a, c) => (c > a ? c : a))
  cont.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner ? `winner ${winner}` : 'no winner'
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${round}\n${end}\n`)
EOF
