import { readFileSync } from 'node:fs'

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]*):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const br = rest.lastIndexOf(']')
  const c = rest.indexOf(':', br + 1)
  return c >= 0
    ? { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
    : { userinfo, host: rest, port: undefined }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function checkPct(label, s) {
  if (s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new Fail(`the ${label} has a truncated percent-encoding`)
  }
}

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function check(u) {
  checkPct('path', u.path)
  if (u.authority !== undefined) {
    const a = splitAuthority(u.authority)
    checkPct('userinfo', a.userinfo)
    checkPct('host', a.host)
  }
  checkPct('query', u.query)
  checkPct('fragment', u.fragment)
}

function normalize(u) {
  let out = ''
  const scheme = u.scheme === undefined ? undefined : lower(u.scheme)
  if (scheme !== undefined) out += scheme + ':'
  let hasAuth = u.authority !== undefined
  if (hasAuth) {
    const a = splitAuthority(u.authority)
    let s = ''
    if (a.userinfo !== undefined) s += pct(a.userinfo) + '@'
    s += lower(pct(a.host))
    if (a.port !== undefined) {
      const p = pct(a.port)
      if (p !== '' && !(scheme !== undefined && DEFAULT_PORT[scheme] === p)) s += ':' + p
    }
    out += '//' + s
  }
  let path = removeDots(pct(u.path))
  if (hasAuth && path === '') path = '/'
  out += path
  if (u.query !== undefined) out += '?' + pct(u.query)
  if (u.fragment !== undefined) out += '#' + pct(u.fragment)
  return out
}

function resolve(base, r) {
  if (r.scheme !== undefined) return { ...r, path: removeDots(r.path) }
  if (r.authority !== undefined) {
    return { ...r, scheme: base.scheme, path: removeDots(r.path) }
  }
  const t = { scheme: base.scheme, authority: base.authority, fragment: r.fragment }
  if (r.path === '') {
    t.path = base.path
    t.query = r.query !== undefined ? r.query : base.query
  } else {
    if (r.path.startsWith('/')) t.path = removeDots(r.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + r.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i >= 0 ? base.path.slice(0, i + 1) + r.path : r.path
      }
      t.path = removeDots(merged)
    }
    t.query = r.query
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new Fail('usage: cli.js normalize|resolve')
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((line, idx) => {
    try {
      let u
      if (args[0] === 'normalize') u = parse(line)
      else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new Fail('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === undefined) throw new Fail('the base has no scheme')
        u = resolve(base, parse(line.slice(sp + 1)))
      }
      check(u)
      out.push(normalize(u))
    } catch (e) {
      if (e instanceof Fail && args[0] && idx >= 0 && !e.message.startsWith('usage')) {
        throw new Fail(`line ${idx + 1}: ${e.message}`)
      }
      throw e
    }
  })
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exitCode = 2
}
