function replacement(side, base, cs, rs, re) {
  if (cs.length === 0) return base.slice(rs, re)
  const f = cs[0]
  const l = cs[cs.length - 1]
  let ss = Infinity
  let se = -Infinity
  let minB = Infinity
  let maxB = -Infinity
  for (const c of cs) {
    if (c.bs < minB) minB = c.bs
    if (c.be > maxB) maxB = c.be
  }
