  ss = f.ss - (f.bs - rs)
  se = l.se + (re - l.be)
  void minB
  void maxB
  return side.slice(ss, se)
}

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  let conflict = false
  let pos = 0
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) regions.push({ kind: 'stable', lines: base.slice(pos, rs) })
    const mc = group.filter(c => c.who === 0)
    const tc = group.filter(c => c.who === 1)
    const m = replacement(mine, base, mc, rs, re)
    const t = replacement(theirs, base, tc, rs, re)
    const b = base.slice(rs, re)
    if (same(m, t)) regions.push({ kind: mc.length && tc.length ? 'both' : mc.length ? 'mine' : 'theirs', lines: m })
    else if (same(m, b)) regions.push({ kind: 'theirs', lines: t })
    else if (same(t, b)) regions.push({ kind: 'mine', lines: m })
    else {
      conflict = true
      regions.push({ kind: 'conflict', mine: m, base: b, theirs: t })
    }
    pos = re
  }
  if (base.length > pos) regions.push({ kind: 'stable', lines: base.slice(pos) })
  return { regions, conflict }
