#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') fail('usage: cli.js replay|summary', true)

function fail(msg, bare) {
  process.stderr.write(`error: ${bare ? '' : ''}${msg}\n`)
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Bucket {
  constructor(name, cap, refill, per) { Object.assign(this, { name, cap, refill, per }); this.state = new Map() }
  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) { s = { units: this.cap * this.per, last: tick }; this.state.set(key, s); return }
    const max = this.cap * this.per
    s.units += this.refill * (tick - s.last)
    if (s.units > max) s.units = max
    s.last = tick
  }
  ask(key) { return this.state.get(key).units >= this.per }
  record(key) { this.state.get(key).units -= this.per }
}

class Window {
  constructor(name, limit, span) { Object.assign(this, { name, limit, span }); this.state = new Map() }
  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) { s = []; this.state.set(key, s) }
    const cut = tick - this.span
    while (s.length && s[0] <= cut) s.shift()
  }
  ask(key) { return BigInt(this.state.get(key).length) < this.limit }
  record(key, tick) { this.state.get(key).push(tick) }
}

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const policies = new Map()
const routes = new Map()
const events = []
let started = false
let lastTick = null

lines.forEach((raw, i) => {
  const n = i + 1
  const err = (m) => fail(`line ${n}: ${m}`)
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const f = line.split(/\s+/)
  const word = f[0]
  const int = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) err(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  if (word === 'bucket') {
    if (f.length !== 5) err('expected bucket <name> <capacity> <refill> <per>')
    if (started) err('declarations must come before the first event')
    if (!NAME.test(f[1])) err(`invalid policy name ${f[1]}`)
    const cap = int(f[2], 'capacity', 1)
    const refill = int(f[3], 'refill', 0)
    const per = int(f[4], 'per', 1)
    if (policies.has(f[1])) err(`policy ${f[1]} is declared twice`)
    policies.set(f[1], new Bucket(f[1], cap, refill, per))
  } else if (word === 'window') {
    if (f.length !== 4) err('expected window <name> <limit> <span>')
    if (started) err('declarations must come before the first event')
    if (!NAME.test(f[1])) err(`invalid policy name ${f[1]}`)
    const limit = int(f[2], 'limit', 0)
